describe('curl user-agent', () => {
  it('injects default UA when absent', async () => {
    const s = await services.settings.getOrCreate();
    await services.settings.update(s, { disableAppVersionUserAgent: false });
    const result = await convert("curl https://example.com -H 'X-Host: example.com'");
    expect(result).toMatchObject([{ headers: [{ name: 'X-Host', value: 'example.com' }, { name: 'User-Agent', value: 'insomnia/1.2.3' }] }]);
  });

  it('preserves existing UA', async () => {
    const s = await services.settings.getOrCreate();
    await services.settings.update(s, { disableAppVersionUserAgent: false });
    const result = await convert("curl https://example.com -H 'user-agent: custom/9'") as any;
    const uas = result[0].headers.filter((h: any) => h.name.toLowerCase() === 'user-agent');
    expect(uas).toEqual([{ name: 'user-agent', value: 'custom/9' }]);
  });

