    const s = await services.settings.getOrCreate();
    await services.settings.update(s, { disableAppVersionUserAgent: true });
    const result = await convert("curl https://example.com -H 'X-Host: example.com'") as any;
    expect(result[0].headers.some((h: any) => h.name.toLowerCase() === 'user-agent')).toBe(false);
    await services.settings.update(await services.settings.getOrCreate(), { disableAppVersionUserAgent: false });
  });

  it('keeps explicit UA when disabled', async () => {
    const s = await services.settings.getOrCreate();
    await services.settings.update(s, { disableAppVersionUserAgent: true });
    const result = await convert("curl https://example.com -H 'User-Agent: custom/9'") as any;
    const uas = result[0].headers.filter((h: any) => h.name.toLowerCase() === 'user-agent');
    expect(uas).toEqual([{ name: 'User-Agent', value: 'custom/9' }]);
    await services.settings.update(await services.settings.getOrCreate(), { disableAppVersionUserAgent: false });
  });
});
